package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen0Test {

    @Test(expected = IOException.class)
    public void testRead_WhenClosed() throws IOException {
        ByteArrayInputStream bais = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(bais);
        zais.close();
        zais.read(new byte[10], 0, 10);
    }

    @Test
    public void testRead_WhenFinishedOrNullEntry() throws IOException {
        ByteArrayInputStream bais = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(bais);

        // current is null initially
        Assert.assertEquals(-1, zais.read(new byte[10], 0, 10));
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_InvalidBufferIndices() throws IOException {
        byte[] content = createZipWithEntry("test", "hello".getBytes());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(content));
        zais.getNextZipEntry();

        // start > buffer.length
        zais.read(new byte[5], 10, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeLength() throws IOException {
        byte[] content = createZipWithEntry("test", "hello".getBytes());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(content));
        zais.getNextZipEntry();

        zais.read(new byte[5], 0, -1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_OverflowLength() throws IOException {
        byte[] content = createZipWithEntry("test", "hello".getBytes());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(content));
        zais.getNextZipEntry();

        // start + length > buffer.length
        zais.read(new byte[5], 2, 4);
    }

    @Test
    public void testRead_DeflatedEntry() throws IOException {
        String data = "This is a test string for deflation";
        byte[] content = createZipWithEntry("test", data.getBytes());

        try (ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(content))) {
            zais.getNextZipEntry();
            byte[] buffer = new byte[10];
            int read = zais.read(buffer, 0, 10);
            Assert.assertTrue(read > 0);
            Assert.assertTrue(read <= 10);
        }
    }

    @Test
    public void testRead_StoredEntry() throws IOException {
        // Using a manual ZIP construction to ensure STORED method is triggered
        byte[] content = createStoredZipWithEntry("stored", "hello".getBytes());

        try (ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(content))) {
            zais.getNextZipEntry();
            byte[] buffer = new byte[10];

            // First read
            int read1 = zais.read(buffer, 0, 2);
            Assert.assertEquals(2, read1);

            // Second read (triggering offsetInBuffer logic)
            int read2 = zais.read(buffer, 0, 2);
            Assert.assertEquals(2, read2);

            // Read remaining
            int read3 = zais.read(buffer, 0, 10);
            Assert.assertTrue(read3 <= 1);
        }
    }

    @Test
    public void testRead_EndOfStreamStored() throws IOException {
        byte[] content = createStoredZipWithEntry("stored", "a".getBytes());
        try (ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(content))) {
            zais.getNextZipEntry();
            byte[] buffer = new byte[10];
            zais.read(buffer, 0, 1); // read 'a'
            int read2 = zais.read(buffer, 0, 1);
            Assert.assertEquals(-1, read2);
        }
    }

    @Test(expected = IOException.class)
    public void testRead_TruncatedZip() throws IOException {
        // Create a zip but provide incomplete data for the deflate stream
        byte[] content = createZipWithEntry("test", "some data".getBytes());
        // Truncate the content to break the deflate stream
        byte[] truncated = new byte[content.length - 5];
        System.arraycopy(content, 0, truncated, 0, truncated.length);

        try (ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(truncated))) {
            zais.getNextZipEntry();
            byte[] buffer = new byte[10];
            zais.read(buffer, 0, 10);
        }
    }

    private byte[] createZipWithEntry(String name, byte[] content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(name);
            zos.putNextEntry(entry);
            zos.write(content);
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    private byte[] createStoredZipWithEntry(String name, byte[] content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(name);
            entry.setMethod(ZipEntry.STORED);
            entry.setSize(content.length);
            entry.setCrc(calculateCRC(content));
            zos.putNextEntry(entry);
            zos.write(content);
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    private long calculateCRC(byte[] content) {
        CRC32 crc = new CRC32();
        crc.update(content);
        return crc.getValue();
    }
}
